// Canvas renderer. The carpet is made of painted chunk images (generated by the Artist); until a
// chunk is painted its layout sketch is shown. Beings and things are generated sprites. Runes stay
// what they are: glowing code. The corona is drawn only once the carpet stops holding you.

import type { Chunk, Kernel } from '../kernel/kernel';
import type { RuneComp } from '../kernel/runes';
import { hash32 } from '../kernel/rng';
import { applyGlitch, randomGlyph } from './glitch';
import type { ImageCache } from './imagetools';

const FONT = '"Cascadia Mono", "JetBrains Mono", Consolas, "DejaVu Sans Mono", monospace';

const RUNE_STYLE = {
  gen: { bg: 'rgba(46, 35, 6, 0.88)', edge: '#ffcf5c', fg: '#ffe7a3' },
  player: { bg: 'rgba(6, 42, 51, 0.88)', edge: '#3fd6f0', fg: '#b8f6ff' },
  broken: { bg: 'rgba(61, 7, 13, 0.9)', edge: '#ff4d5e', fg: '#ff9aa4' },
};

function shade(hex: string, k: number): string {
  const m = /^#?([0-9a-f]{6})$/i.exec(hex);
  if (!m) return hex;
  const n = parseInt(m[1], 16);
  const f = (v: number) => Math.max(0, Math.min(255, Math.round(v * k)));
  return `rgb(${f(n >> 16)}, ${f((n >> 8) & 255)}, ${f(n & 255)})`;
}

export class Renderer {
  cell = 40;
  private ctx: CanvasRenderingContext2D;
  private dpr = 1;
  private w = 0;
  private h = 0;
  private sketches = new Map<string, { version: number; canvas: HTMLCanvasElement }>();
  private cam = { x: 0, y: 0 };
  private glitch = 0;
  private crack = 0;
  private t = 0;
  mouse: { x: number; y: number } | null = null;

  constructor(
    private canvas: HTMLCanvasElement,
    private kernel: Kernel,
    private images: ImageCache,
  ) {
    this.ctx = canvas.getContext('2d')!;
    this.resize();
    window.addEventListener('resize', () => this.resize());
    kernel.bus.on('universe:reloaded', () => this.sketches.clear());
    canvas.addEventListener('mousemove', (e) => (this.mouse = { x: e.offsetX, y: e.offsetY }));
    canvas.addEventListener('mouseleave', () => (this.mouse = null));
  }

  resize(): void {
    this.dpr = Math.min(window.devicePixelRatio || 1, 2);
    this.w = this.canvas.clientWidth;
    this.h = this.canvas.clientHeight;
    this.canvas.width = Math.floor(this.w * this.dpr);
    this.canvas.height = Math.floor(this.h * this.dpr);
    this.cell = this.w < 700 ? 28 : 40;
    this.kernel.view = { w: Math.ceil(this.w / this.cell) + 2, h: Math.ceil(this.h / this.cell) + 2 };
    this.sketches.clear();
  }

  /** Screen → real-space coordinates. */
  toReal(sx: number, sy: number): { x: number; y: number } {
    return { x: (sx - this.w / 2) / this.cell + this.cam.x, y: (sy - this.h / 2) / this.cell + this.cam.y };
  }

  private sx(rx: number): number {
    return (rx - this.cam.x) * this.cell + this.w / 2;
  }

  private sy(ry: number): number {
    return (ry - this.cam.y) * this.cell + this.h / 2;
  }

  render(dt: number): void {
    const k = this.kernel;
    const ctx = this.ctx;
    const C = this.cell;
    this.t += dt;
    const p = k.playerPos();
    const follow = Math.min(1, dt * 10);
    this.cam.x += (p.x - this.cam.x) * follow;
    this.cam.y += (p.y - this.cam.y) * follow;

    const target = k.brokenness();
    this.glitch += (target - this.glitch) * Math.min(1, dt * 4);
    if (target === 0 && Math.random() < dt / 30) this.crack = 0.12;
    this.crack = Math.max(0, this.crack - dt);
    const g = Math.max(this.glitch, this.crack > 0 ? 0.22 : 0);

    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    ctx.fillStyle = '#030406';
    ctx.fillRect(0, 0, this.w, this.h);
    if (g > 0.2) ctx.translate((Math.random() - 0.5) * 4 * g, (Math.random() - 0.5) * 3 * g);

    const revealed = k.coronaRevealed();
    if (revealed) this.drawCorona();

    const R = k.config.circleRadius;
    const { ox, oy } = k.offset();
    ctx.save();
    if (revealed) {
      ctx.beginPath();
      ctx.arc(this.sx(0), this.sy(0), R * C, 0, Math.PI * 2);
      ctx.clip();
      ctx.fillStyle = '#07090a';
      ctx.fillRect(0, 0, this.w, this.h);
    }

    const S = k.config.chunkSize;
    ctx.imageSmoothingEnabled = true;
    for (const ch of k.chunks.values()) {
      const x = Math.round(this.sx(ch.cx * S - ox));
      const y = Math.round(this.sy(ch.cy * S - oy));
      if (x > this.w || y > this.h || x + S * C < 0 || y + S * C < 0) continue;
      const img = this.images.peek(ch.image);
      // +1px overlap hides seams between neighbouring chunk images.
      if (img) ctx.drawImage(img, x, y, S * C + 1, S * C + 1);
      else ctx.drawImage(this.sketch(ch), x, y, S * C, S * C);
      if (ch.painting) {
        ctx.fillStyle = `rgba(255, 138, 216, ${0.06 + 0.05 * Math.sin(this.t * 4)})`;
        ctx.fillRect(x, y, S * C, S * C);
      }
    }

    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    this.drawRunes(ox, oy, g);
    this.drawEntities(ox, oy, g);
    ctx.restore();

    if (revealed) {
      const d = Math.hypot(p.x, p.y);
      const near = Math.max(0, 1 - (R - d) / 10);
      if (near > 0) {
        ctx.strokeStyle = `rgba(120, 255, 180, ${0.15 + 0.5 * near})`;
        ctx.lineWidth = 1.5;
        ctx.setLineDash([4, 6]);
        ctx.beginPath();
        ctx.arc(this.sx(0), this.sy(0), R * C, 0, Math.PI * 2);
        ctx.stroke();
        ctx.setLineDash([]);
      }
    }

    this.drawPlayer(g);
    this.drawBubbles(ox, oy);
    this.drawHover();
    if (g > 0.05) this.drawCorruption(g);
    applyGlitch(ctx, this.canvas, g, this.dpr);
  }

  /** The Cartographer's layout, shown until the Artist paints it. */
  private sketch(ch: Chunk): HTMLCanvasElement {
    const cached = this.sketches.get(ch.key);
    if (cached && cached.version === ch.version) return cached.canvas;
    const k = this.kernel;
    const S = k.config.chunkSize;
    const T = 16;
    const canvas = cached?.canvas ?? document.createElement('canvas');
    canvas.width = S * T;
    canvas.height = S * T;
    const c = canvas.getContext('2d')!;
    for (let row = 0; row < S; row++)
      for (let col = 0; col < S; col++) {
        const t = k.palette[ch.tiles[row * S + col]] ?? k.palette['?'];
        c.fillStyle = t.color;
        c.fillRect(col * T, row * T, T, T);
        // A little deterministic texture, so the sketch reads as ground and not as a spreadsheet.
        for (let i = 0; i < 5; i++) {
          const h = hash32(ch.cx * S + col, ch.cy * S + row, i);
          c.fillStyle = shade(t.color, 0.82 + ((h >>> 8) % 30) / 100);
          c.fillRect(col * T + (h % T), row * T + ((h >>> 4) % T), 2 + (h % 3), 2);
        }
        if (t.solid) {
          c.fillStyle = 'rgba(0,0,0,0.18)';
          c.fillRect(col * T, row * T + T - 3, T, 3);
        }
      }
    if (ch.stage === 'draft') {
      c.fillStyle = 'rgba(3,4,6,0.45)';
      c.fillRect(0, 0, S * T, S * T);
    }
    this.sketches.set(ch.key, { version: ch.version, canvas });
    return canvas;
  }

  private drawRunes(ox: number, oy: number, g: number): void {
    const k = this.kernel;
    const ctx = this.ctx;
    const C = this.cell;
    const pulse = 0.7 + 0.3 * Math.sin(this.t * 3);
    ctx.font = `bold ${Math.round(C * 0.62)}px ${FONT}`;
    for (const id of k.ecs.query('rune')) {
      const r: RuneComp = k.ecs.get(id, 'rune');
      const x0 = this.sx(r.col - ox);
      const y0 = this.sy(r.row - oy);
      if (x0 > this.w || y0 > this.h || x0 + r.token.length * C < 0 || y0 + C < 0) continue;
      const line = k.lineOfRune(id);
      const style = line?.error ? RUNE_STYLE.broken : RUNE_STYLE[r.source];
      const jitter = line?.error ? (Math.random() - 0.5) * 2 : 0;
      const pad = C * 0.12;
      ctx.fillStyle = style.bg;
      ctx.fillRect(x0 + pad / 2, y0 + pad, r.token.length * C - pad, C - pad * 2);
      ctx.globalAlpha = pulse;
      ctx.shadowColor = style.edge;
      ctx.shadowBlur = 8;
      ctx.strokeStyle = style.edge;
      ctx.lineWidth = 1.5;
      ctx.strokeRect(x0 + pad / 2, y0 + pad, r.token.length * C - pad, C - pad * 2);
      ctx.shadowBlur = 0;
      ctx.globalAlpha = 1;
      ctx.fillStyle = style.fg;
      for (let i = 0; i < r.token.length; i++) {
        const ch = g > 0.3 && Math.random() < g * 0.05 ? randomGlyph() : r.token[i];
        ctx.fillText(ch, x0 + i * C + C / 2 + jitter, y0 + C / 2 + 1);
      }
    }
  }

  private drawEntities(ox: number, oy: number, g: number): void {
    const k = this.kernel;
    const ctx = this.ctx;
    const C = this.cell;
    const pc = k.playerCarpet();
    const ids = k.ecs.query('glyph', 'pos').filter((id) => id !== k.playerId);
    ids.sort((a, b) => k.ecs.get(a, 'pos').y - k.ecs.get(b, 'pos').y);
    let hint: { x: number; y: number; d: number } | null = null;
    for (const id of ids) {
      const p = k.ecs.get(id, 'pos');
      const gl = k.ecs.get(id, 'glyph');
      const x = this.sx(p.x - ox);
      const y = this.sy(p.y - oy);
      if (x < -C * 2 || y < -C * 2 || x > this.w + C * 2 || y > this.h + C * 2) continue;
      const size = C * (gl.scale ?? 1.1);
      const img = this.images.peek(gl.sprite);
      const bob = k.ecs.has(id, 'pickup') ? Math.sin(this.t * 3 + id) * C * 0.05 : 0;
      ctx.fillStyle = 'rgba(0,0,0,0.25)';
      ctx.beginPath();
      ctx.ellipse(x, y + size * 0.36, size * 0.32, size * 0.12, 0, 0, Math.PI * 2);
      ctx.fill();
      if (img && !(g > 0.4 && Math.random() < 0.08)) ctx.drawImage(img, x - size / 2, y - size / 2 - size * 0.15 + bob, size, size);
      else {
        ctx.fillStyle = 'rgba(0,0,0,0.55)';
        ctx.beginPath();
        ctx.arc(x, y + bob, size * 0.38, 0, Math.PI * 2);
        ctx.fill();
        ctx.font = `${Math.round(size * 0.6)}px ${FONT}`;
        ctx.fillStyle = gl.color;
        ctx.fillText(g > 0.4 && Math.random() < 0.1 ? randomGlyph() : String(gl.ch), x, y + 1 + bob);
      }
      if (k.ecs.has(id, 'interact') || k.ecs.has(id, 'pickup')) {
        const d = Math.hypot(p.x - pc.x, p.y - pc.y);
        if (d < 1.7 && (!hint || d < hint.d)) hint = { x, y: y - size * 0.75, d };
      }
    }
    if (hint) {
      ctx.font = `bold ${Math.round(C * 0.4)}px ${FONT}`;
      ctx.fillStyle = 'rgba(3,6,5,0.85)';
      ctx.fillRect(hint.x - C * 0.25, hint.y - C * 0.25, C * 0.5, C * 0.5);
      ctx.strokeStyle = '#ffcf5c';
      ctx.lineWidth = 1;
      ctx.strokeRect(hint.x - C * 0.25, hint.y - C * 0.25, C * 0.5, C * 0.5);
      ctx.fillStyle = '#ffcf5c';
      ctx.fillText('E', hint.x, hint.y + 1);
    }
  }

  private drawPlayer(g: number): void {
    const k = this.kernel;
    const ctx = this.ctx;
    const C = this.cell;
    const p = k.playerPos();
    const gl = k.ecs.get(k.playerId, 'glyph') ?? { ch: '@', color: '#fff' };
    const x = this.sx(p.x);
    const y = this.sy(p.y);
    const size = C * (gl.scale ?? 1.3);
    ctx.fillStyle = 'rgba(0,0,0,0.3)';
    ctx.beginPath();
    ctx.ellipse(x, y + size * 0.36, size * 0.3, size * 0.11, 0, 0, Math.PI * 2);
    ctx.fill();
    const img = this.images.peek(gl.sprite);
    if (img && !(g > 0.5 && Math.random() < 0.15)) ctx.drawImage(img, x - size / 2, y - size / 2 - size * 0.15, size, size);
    else {
      ctx.fillStyle = 'rgba(255,255,255,0.12)';
      ctx.beginPath();
      ctx.arc(x, y, size * 0.45, 0, Math.PI * 2);
      ctx.fill();
      ctx.font = `bold ${Math.round(size * 0.7)}px ${FONT}`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillStyle = gl.color;
      ctx.fillText(g > 0.5 && Math.random() < 0.15 ? randomGlyph() : gl.ch, x, y + 1);
    }
    const f = k.playerComp()?.facing;
    const [dx, dy] = f === 'left' ? [-1, 0] : f === 'right' ? [1, 0] : f === 'up' ? [0, -1] : [0, 1];
    ctx.fillStyle = 'rgba(255,255,255,0.6)';
    ctx.beginPath();
    ctx.arc(x + dx * size * 0.55, y + dy * size * 0.55, 2.5, 0, Math.PI * 2);
    ctx.fill();
    // What you hold.
    const inv = k.inventory();
    const held = inv.equipped !== null ? inv.slots[inv.equipped]?.item : undefined;
    if (held) {
      const info = k.itemInfo(held);
      const himg = this.images.peek(info.sprite);
      const hs = C * 0.55;
      const hx = x + size * 0.38;
      const hy = y + size * 0.05;
      if (himg) ctx.drawImage(himg, hx - hs / 2, hy - hs / 2, hs, hs);
      else {
        ctx.font = `${Math.round(hs * 0.8)}px ${FONT}`;
        ctx.fillStyle = info.color;
        ctx.fillText(info.glyph, hx, hy);
      }
    }
  }

  private drawBubbles(ox: number, oy: number): void {
    const k = this.kernel;
    const ctx = this.ctx;
    const C = this.cell;
    ctx.font = `13px ${FONT}`;
    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    for (const [id, b] of k.bubbles) {
      const p = k.ecs.get(id, 'pos');
      if (!p) continue;
      const x = this.sx(p.x - ox);
      const y = this.sy(p.y - oy) - C * 1.1;
      const words = b.text.split(/\s+/);
      const lines: string[] = [];
      let cur = '';
      for (const w of words) {
        if ((cur + ' ' + w).trim().length > 34) {
          lines.push(cur.trim());
          cur = w;
        } else cur += ' ' + w;
      }
      if (cur.trim()) lines.push(cur.trim());
      const shown = lines.slice(0, 4);
      const bw = Math.max(...shown.map((l) => ctx.measureText(l).width)) + 16;
      const bh = shown.length * 16 + 10;
      const bx = Math.min(Math.max(8, x - bw / 2), this.w - bw - 8);
      const by = y - bh;
      ctx.fillStyle = 'rgba(250, 244, 228, 0.95)';
      ctx.strokeStyle = 'rgba(40, 30, 10, 0.9)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.roundRect(bx, by, bw, bh, 6);
      ctx.fill();
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(x - 5, by + bh);
      ctx.lineTo(x, by + bh + 7);
      ctx.lineTo(x + 5, by + bh);
      ctx.fill();
      ctx.fillStyle = '#2a2010';
      shown.forEach((l, i) => ctx.fillText(l, bx + 8, by + 5 + i * 16));
    }
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
  }

  private drawCorona(): void {
    const k = this.kernel;
    const corona = k.corona;
    const C = this.cell;
    const halfW = this.w / 2 / C + 1;
    const halfH = this.h / 2 / C + 1;
    const camD = Math.hypot(this.cam.x, this.cam.y);
    if (camD + Math.hypot(halfW, halfH) < corona.radius) return;
    const ctx = this.ctx;
    ctx.font = `${Math.round(C * 0.6)}px ${FONT}`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    const p = k.playerPos();
    const here = corona.at(Math.floor(p.x), Math.floor(p.y));
    const x0 = Math.floor(this.cam.x - halfW);
    const y0 = Math.floor(this.cam.y - halfH);
    for (let y = y0; y < this.cam.y + halfH; y++) {
      for (let x = x0; x < this.cam.x + halfW; x++) {
        const cell = corona.at(x, y);
        if (!cell || cell.kind === 'empty') continue;
        const sameFile = here?.path && cell.path === here.path;
        let color: string;
        let ch = cell.ch;
        if (cell.kind === 'header') color = '#ffcf5c';
        else if (cell.kind === 'eof') color = '#ff4d5e';
        else if (ch === '\n') {
          ch = '↵';
          color = '#1c3a2a';
        } else color = sameFile ? '#7dffb0' : '#2f7a52';
        if (ch === ' ') continue;
        if (sameFile && here?.line === cell.line && cell.kind === 'code') {
          ctx.fillStyle = '#0f2e1f';
          ctx.fillRect(this.sx(x), this.sy(y), C, C);
          color = '#d6ffe6';
        }
        ctx.fillStyle = color;
        ctx.fillText(ch, this.sx(x) + C / 2, this.sy(y) + C / 2 + 1);
      }
    }
  }

  private drawHover(): void {
    if (!this.mouse) return;
    const r = this.toReal(this.mouse.x, this.mouse.y);
    const C = this.cell;
    const k = this.kernel;
    const { ox, oy } = k.offset();
    const inCorona = k.coronaRevealed() && Math.hypot(r.x, r.y) >= k.config.circleRadius;
    const x = inCorona ? Math.floor(r.x) : Math.floor(r.x + ox) - ox;
    const y = inCorona ? Math.floor(r.y) : Math.floor(r.y + oy) - oy;
    this.ctx.strokeStyle = 'rgba(255,255,255,0.35)';
    this.ctx.lineWidth = 1;
    this.ctx.strokeRect(this.sx(x) + 0.5, this.sy(y) + 0.5, C - 1, C - 1);
  }

  private drawCorruption(g: number): void {
    const ctx = this.ctx;
    const C = this.cell;
    ctx.font = `${Math.round(C * 0.6)}px ${FONT}`;
    const n = Math.floor(g * 40);
    for (let i = 0; i < n; i++) {
      const x = Math.floor(Math.random() * (this.w / C)) * C;
      const y = Math.floor(Math.random() * (this.h / C)) * C;
      ctx.fillStyle = '#000';
      ctx.fillRect(x, y, C, C);
      ctx.fillStyle = Math.random() < 0.5 ? '#ff2a6d' : '#05d9e8';
      ctx.fillText(randomGlyph(), x + C / 2, y + C / 2 + 1);
    }
  }
}
